create or replace function private.schoolpro_cached_family_result_periods() returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_object_agg(q.student_id::text||'|'||q.term||'|'||q.session,true),'{}'::jsonb) from(select distinct r.student_id,r.term,r.session from public.schoolpro_results r join public.schoolpro_students s on s.id=r.student_id and s.school_id=r.school_id where (select private.is_active_account()) and (s.user_id=(select auth.uid()) or exists(select 1 from public.schoolpro_guardian_links g where g.student_id=s.id and g.school_id=s.school_id and g.guardian_user_id=(select auth.uid()) and g.status='active')))q cross join lateral private.schoolpro_result_access(q.student_id,q.term,q.session) access where access.allowed$$;
revoke all on function private.schoolpro_cached_family_result_periods() from public,anon;
grant execute on function private.schoolpro_cached_family_result_periods() to authenticated,service_role;
alter policy "Result access gate" on public.schoolpro_results using((select private.is_active_account()) and case when school_id=any((select private.schoolpro_cached_access_schools('results','result-leader'))::uuid[]) then true else (school_id=any((select private.schoolpro_cached_staff_schools())::uuid[]) or (select private.schoolpro_cached_family_result_periods()) ? (student_id::text||'|'||term||'|'||session)) end);
